export const COUNT_LINES = () => { let n = 0; const walk = (o) => { if (Array.isArray(o)) { for (const x of o) typeof x === 'string' ? n++ : walk(x); } else if (o && typeof o === 'object') for (const v of Object.values(o)) { if (typeof v === 'string') n++; else walk(v); } }; walk(TYPE_LINES); walk(UNIQUE); walk(GOSSIP); walk(GANDER); walk(HOSTS); walk(BALLAD); walk(BEDTIME); walk(LETTER_REPLY); walk(GRAN_LETTERS); walk(FESTIVAL_LINES); return n; };
